package com.netbanking.account.exception;
import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestControllerAdvice public class ApiExceptionHandler { @ExceptionHandler(NotFoundException.class) ResponseEntity<?> notFound(RuntimeException e){return error(HttpStatus.NOT_FOUND,e);} @ExceptionHandler({ConflictException.class,IllegalStateException.class}) ResponseEntity<?> conflict(RuntimeException e){return error(HttpStatus.CONFLICT,e);} @ExceptionHandler(IllegalArgumentException.class) ResponseEntity<?> badRequest(RuntimeException e){return error(HttpStatus.BAD_REQUEST,e);} private ResponseEntity<Map<String,String>> error(HttpStatus status,RuntimeException e){return ResponseEntity.status(status).body(Map.of("error",e.getMessage()));} }
